import math
import re

# Rounded SVG coordinates: geometric comparisons allow small rounding errors.
EPS = 4e-5
PATH = """
M 24.38698,-19.9365 L 29.3405,-17.62663
M 0.0,7.0 L 0.0,5.46
M 10.35209,0.0 L 10.35209,-7.0986
M 20.49493,-28.84999 L 17.75636,-22.97711
M 20.49493,-21.75139 L 24.38698,-19.9365
M 18.29129,-17.02568 L 20.49493,-21.75139
M 17.75636,-22.97711 L 15.16487,-17.41963
M 10.35209,-7.0986 L 0.0,-7.0986
M 22.10067,8.68911 L 19.34832,10.61633
M 2.5205,-5.64339 L 6.14757,-3.5493
M 10.35209,-4.68508 L 10.35209,0.0
M 10.35209,-7.0986 L 10.35209,-4.68508
M 20.49493,-25.44266 L 20.49493,-28.84999
M 0.0,-7.0986 L 2.5205,-5.64339
M 6.14757,-3.5493 L 2.33608,-1.34873
M 24.85302,6.76189 L 22.10067,8.68911
M 15.93065,-11.96326 L 17.25429,-14.80182
M 20.49493,-21.75139 L 20.49493,-25.44266
M 19.34832,10.61633 L 17.21983,12.10671 L 11.74658,15.93912
M 10.35209,1.96 L 10.35209,3.3712
M 0.0,5.46 L 0.0,0.0
M 4.03732,0.0 L 10.35209,0.0
M 10.35209,7.0 L 7.55703,7.0
M 10.35209,0.0 L 15.93065,-11.96326
M 10.35209,3.3712 L 10.35209,7.0
M 2.33608,-1.34873 L 0.0,0.0
M 34.99586,-14.98949 L 24.85302,6.76189
M 15.16487,-17.41963 L 10.35209,-7.0986
M 11.74658,15.93912 L 11.17484,9.40408
M 0.0,0.0 L 4.03732,0.0
M 11.17484,9.40408 L 10.79637,5.0782
M 29.3405,-17.62663 L 34.99586,-14.98949
M 10.35209,0.0 L 10.35209,1.96
M 10.79637,5.0782 L 10.35209,0.0
M 7.55703,7.0 L 0.0,7.0
M 17.25429,-14.80182 L 18.29129,-17.02568
"""

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def length(v):
    return math.hypot(*v)

def on_segment(p, a, b):
    v = sub(b, a)
    w = sub(p, a)
    d = length(v)
    if d < EPS:
        return length(w) <= EPS
    return (abs(cross(v, w)) <= EPS * d
            and -EPS * d <= dot(w, v) <= dot(v, v) + EPS * d)

segments = []
previous = None
pattern = r"([ML])\s*(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)"
for command, x, y in re.findall(pattern, PATH):
    p = (float(x), float(y))
    if command == "L":
        segments.append((previous, p))
    previous = p

# Construct the complete planar graph, splitting at all intersections.
points = []
def point_id(p):
    for i, q in enumerate(points):
        if length(sub(p, q)) <= EPS:
            return i
    points.append(p)
    return len(points) - 1

for a, b in segments:
    point_id(a)
    point_id(b)

for i, (a, b) in enumerate(segments):
    r = sub(b, a)
    for c, d in segments[i + 1:]:
        s = sub(d, c)
        denominator = cross(r, s)
        if abs(denominator) <= 1e-10 * length(r) * length(s):
            continue
        t = cross(sub(c, a), s) / denominator
        u = cross(sub(c, a), r) / denominator
        if (-EPS / length(r) <= t <= 1 + EPS / length(r)
                and -EPS / length(s) <= u <= 1 + EPS / length(s)):
            point_id((a[0] + t * r[0], a[1] + t * r[1]))

edges = set()
for a, b in segments:
    v = sub(b, a)
    ids = [i for i, p in enumerate(points) if on_segment(p, a, b)]
    ids.sort(key=lambda i: dot(sub(points[i], a), v))
    for i, j in zip(ids, ids[1:]):
        if i != j:
            edges.add(tuple(sorted((i, j))))

adj = [set() for _ in points]
for i, j in edges:
    adj[i].add(j)
    adj[j].add(i)

# Exhaustively enumerate simple cycles; the smallest vertex fixes the start,
# and the orientation condition removes reverse duplicates.
cycles = []
for start in range(len(points)):
    path = [start]
    used = {start}

    def visit(v):
        for w in sorted(adj[v]):
            if w == start:
                if len(path) >= 3 and path[1] < path[-1]:
                    cycles.append(tuple(path))
            elif w > start and w not in used:
                used.add(w)
                path.append(w)
                visit(w)
                path.pop()
                used.remove(w)

    visit(start)

def simplify(poly):
    poly = list(poly)
    changed = True
    while changed and len(poly) > 3:
        changed = False
        for i in range(len(poly)):
            a, b, c = poly[i - 1], poly[i], poly[(i + 1) % len(poly)]
            if on_segment(b, a, c):
                poly.pop(i)
                changed = True
                break
    return poly

def strictly_inside(p, poly):
    if any(on_segment(p, a, b)
           for a, b in zip(poly, poly[1:] + poly[:1])):
        return False
    inside = False
    for a, b in zip(poly, poly[1:] + poly[:1]):
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if p[0] < x:
                inside = not inside
    return inside

def has_internal_line(poly):
    # Every graph edge is split at all crossings, so an edge's midpoint
    # determines whether its open interior is inside the cycle.
    for i, j in edges:
        a, b = points[i], points[j]
        midpoint = ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
        if strictly_inside(midpoint, poly):
            return True
    return False

def parallel(a, b):
    return abs(cross(a, b)) <= EPS * (length(a) + length(b))

def perpendicular(a, b):
    return abs(dot(a, b)) <= EPS * (length(a) + length(b))

def equal_lengths(values):
    return max(values) - min(values) <= 3 * EPS

def classify(poly):
    n = len(poly)
    vectors = [sub(poly[(i + 1) % n], poly[i]) for i in range(n)]
    lengths = [length(v) for v in vectors]
    turns = [cross(vectors[i], vectors[(i + 1) % n]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    result = set()

    # Triangles have no possible diagonals.
    if n == 3:
        right = any(perpendicular(vectors[i], vectors[(i + 1) % n])
                    for i in range(n))
        result.add(4 if right else 3)
        return result

    if has_internal_line(poly):
        return result

    if n == 4 and convex:
        pairs = (parallel(vectors[0], vectors[2]),
                 parallel(vectors[1], vectors[3]))
        rectangle = all(perpendicular(vectors[i], vectors[(i + 1) % n])
                        for i in range(n))
        if rectangle:
            result.add(2 if equal_lengths(lengths) else 1)
        elif all(pairs):
            result.add(5)
        elif sum(pairs) == 1:
            result.add(6)

    cosines = [
        dot(vectors[i], vectors[(i + 1) % n])
        / (lengths[i] * lengths[(i + 1) % n])
        for i in range(n)
    ]
    regular = (convex and equal_lengths(lengths)
               and max(cosines) - min(cosines) <= 2e-5)

    if n == 5:
        result.add(9 if regular else (7 if convex else 8))
    if n == 6 and regular:
        result.add(10)
    return result

witnesses = {}
for cycle in cycles:
    poly = simplify([points[i] for i in cycle])
    for shape in classify(poly):
        witnesses.setdefault(shape, []).append(poly)

options = {
    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5},
    "E": {1, 5, 7, 8}, "F": {1, 5, 7, 8, 4, 6},
    "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2},
    "N": {1, 8, 2, 4, 9}, "O": {1, 5, 7, 8, 10},
    "P": {1, 7, 8, 6},
}
found = set(witnesses)
print("Exhaustively enumerated simple cycles:", len(cycles))
print("Detected shape numbers:", sorted(found))
for shape in sorted(found):
    print("Shape", shape, "witness vertices:", witnesses[shape][0])
print("Matching options:", [k for k, v in options.items() if v == found])
print("Submitted E represents:", sorted(options["E"]))
print("CHECK PASS" if found == options["E"] else "CHECK FAIL")
